package com.xauusd.mobileengine; import android.app.*;import android.os.*;import android.graphics.Color;import android.widget.*;import java.util.concurrent.*; public class MainActivity extends Activity{CandleChartView chart;TextView status;ScheduledExecutorService ex;public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setBackgroundColor(Color.rgb(10,12,15));status=new TextView(this);status.setTextColor(Color.WHITE);status.setTextSize(18);status.setPadding(20,12,20,12);status.setText("BIQUOTE • connecting...");r.addView(status,new LinearLayout.LayoutParams(-1,65));chart=new CandleChartView(this);r.addView(chart,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);new Thread(()->{try{Candle[] c=BiquoteClient.candles();runOnUiThread(()->chart.setData(c));}catch(Exception e){runOnUiThread(()->status.setText("Candle error: "+e.getClass().getSimpleName()));}}).start();ex=Executors.newSingleThreadScheduledExecutor();ex.scheduleAtFixedRate(()->{try{double[] t=BiquoteClient.tick();runOnUiThread(()->{chart.setTick(t[0],t[1],"LIVE • Biquote");status.setText(String.format(java.util.Locale.US,"LIVE XAUUSD  BID %.2f  ASK %.2f",t[0],t[1]));});}catch(Exception e){runOnUiThread(()->status.setText("OFFLINE • retrying"));}},1,1,TimeUnit.SECONDS);}protected void onDestroy(){if(ex!=null)ex.shutdownNow();super.onDestroy();}}